    desc: "「初めて夜に、誰にも言わずに外に出た。」 女子がニガテな中学２年生の夜守コウはただ今、なんとなく不登校中。 さらには、夜に眠れない日々が続いている。 そんなある日、コウは初めて夜に、誰にも言わずに外に出た。 夜風が気持ちよく、どこまでも自由で、昼間とちがう世界。コウは夜に居場所を見つける。 そこに突如、謎の美少女・七草ナズナが現れる。 彼女は、夜の住人・吸血鬼。 コウに、夜の楽しさを教えてくれるナズナ。 「今日に満足できるまで、夜ふかししてみろよ。少年」 夜に、そしてナズナに魅了されていくコウは、彼女に頼み込む。 「俺を吸血鬼にしてください」 ナズナは吸血鬼になる条件を教える。照れながら。それは…… 「人が、吸血鬼に恋をすること！」 果たして恋を知らないコウは、ナズナと恋をして、晴れて吸血鬼になれるのか!? ふたりぼっちの、特別な「よふかし」が始まる＿＿",
