    desc: "大陸の中央に位置するとある大国。その国の帝の妃たちが住む後宮に一人の娘がいた。 名前は、猫猫（マオマオ）。 花街で薬師をやっていたが、現在は後宮で下働き中である。 ある日、帝の御子たちが皆短命であることを知る。 今現在いる二人の御子もともに病で次第に弱っている話を聞いた猫猫は、興味本位でその原因を調べ始める。呪いなどあるわけないと言わんばかりに。 美形の宦官・壬氏(ジンシ)は、猫猫を帝の寵妃の毒見役にする。 人間には興味がないが、毒と薬の執着は異常、そんな花街育ちの薬師が巻き込まれる噂や事件。 きれいな薔薇にはとげがある、女の園は毒だらけ、噂と陰謀事欠かず。 壬氏からどんどん面倒事を押し付けられながらも、仕事をこなしていく猫猫。 稀代の毒好き娘が今日も後宮内を駆け回る。",
