    desc: "「リリエーーール!!!」 3次元の女子に興味無し！漫画研究部部長・奥村は今日も部室でひとり、画面の向こうに映る愛してやまない2次元のキャラクター・リリエルの名を叫んでいた……。 そんな奥村のもとへやってきたのは「リリエルになりたい」という3次元女子・天乃リリサ。彼女は、漫画の中に登場する女の子のエッチで可愛い「衣装」が大好き。 そして、奥村に負けないくらいリリエルを愛する仲間（オタク）だった！　奥村に秘密の趣味がコスプレであることを明かしたリリサは、コスプレの写真や動画が詰め込まれた「ROM（ロム）」のコレクションを見せて伝える――。 「私っ……これを作りたいんです!!」 ふたりきりの部室で始まるコスプレ活動！　リリサが変身（コスプレ）したリリエルは奥村が衝撃を受けるほど本物（リアル）で!? 熱意に押された奥村もカメラを手に!?　真摯に熱くコスプレに向き合う彼らが、「何かを熱烈に愛している」全てのオタクへ贈るコスプレ青春ストーリー、開幕!!",
